create table public.management_budgets(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,campaign_id uuid not null references public.campaigns(id)on delete cascade,activity public.production_activity not null,budget_revenue_ars numeric(18,2)not null default 0,budget_cost_ars numeric(18,2)not null default 0,forecast_revenue_ars numeric(18,2)not null default 0,forecast_cost_ars numeric(18,2)not null default 0,assumption_note text,updated_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),unique(farm_id,campaign_id,activity));
create table public.monthly_closures(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,period_start date not null,livestock_reconciled boolean not null default false,inventory_reconciled boolean not null default false,crops_updated boolean not null default false,work_orders_updated boolean not null default false,expenses_allocated boolean not null default false,sales_updated boolean not null default false,cash_reconciled boolean not null default false,projections_reviewed boolean not null default false,status text not null default 'abierto'check(status in('abierto','en_revision','cerrado')),notes text,updated_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),unique(farm_id,period_start),check(date_trunc('month',period_start)=period_start));
alter table public.management_budgets enable row level security;alter table public.monthly_closures enable row level security;create policy budgets_access on public.management_budgets for all to authenticated using(public.can_access_farm(farm_id))with check(public.is_super_admin());create policy closes_access on public.monthly_closures for all to authenticated using(public.can_access_farm(farm_id))with check(public.can_manage_farm(farm_id));
create view public.management_control with(security_invoker=true)as select b.id,b.farm_id,f.name farm_name,b.campaign_id,b.activity,b.budget_revenue_ars,b.budget_cost_ars,(b.budget_revenue_ars-b.budget_cost_ars)budget_margin_ars,b.forecast_revenue_ars,b.forecast_cost_ars,(b.forecast_revenue_ars-b.forecast_cost_ars)forecast_margin_ars,(b.forecast_revenue_ars-b.forecast_cost_ars)-(b.budget_revenue_ars-b.budget_cost_ars)margin_variance_ars,m.income_ars actual_revenue_ars,m.costs_ars actual_cost_ars,m.margin_ars actual_margin_ars,b.assumption_note from public.management_budgets b join public.farms f on f.id=b.farm_id left join public.farm_activity_margins m on m.farm_id=b.farm_id and m.campaign_id=b.campaign_id and m.activity=b.activity;grant select on public.management_control to authenticated;
create view public.monthly_close_status with(security_invoker=true)as select c.*,f.name farm_name,round((c.livestock_reconciled::int+c.inventory_reconciled::int+c.crops_updated::int+c.work_orders_updated::int+c.expenses_allocated::int+c.sales_updated::int+c.cash_reconciled::int+c.projections_reviewed::int)*100.0/8,0)completion_percent,(select count(*)from public.expenses e where e.farm_id=c.farm_id and e.status<>'anulado'and not exists(select 1 from public.expense_allocations a where a.expense_id=e.id))unallocated_expenses from public.monthly_closures c join public.farms f on f.id=c.farm_id;grant select on public.monthly_close_status to authenticated;
